var COM = {"0": "<p>Errado. Art. 47, § 1º, I: vedada, em qualquer hipótese.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "1": "<p>Certo. Art. 47, § 1º, II.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "2": "<p>Certo. Art. 47, § 3º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "3": "<p>Errado. Art. 48, parágrafo único: depende do destaque dos valores corretos.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "4": "<p>Certo. Art. 47, § 6º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "5": "<p>Errado. Art. 47, § 10: não acarreta estorno, salvo previsão expressa.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "6": "<p>Certo. Art. 49, caput.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "7": "<p>Certo. Art. 51, caput e § 2º, I.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "8": "<p>Certo. Art. 47, § 8º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "9": "<p>Errado. Art. 47, § 13, II: não pode ser creditado.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "10": "<p>Errado. Art. 55, caput: vedada a transferência, a qualquer título.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "11": "<p>Certo. Art. 54.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "12": "<p>Certo. Art. 53, I.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "13": "<p>Errado. Art. 53, § 2º: valor nominal.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "14": "<p>Certo. Art. 56.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "15": "<p>Certo. Art. 57, § 3º, IV, a.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "16": "<p>Errado. Art. 57, § 3º, I: não é uso pessoal se comercializadas.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "17": "<p>Certo. Art. 57, § 3º, IV, c.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "18": "<p>Errado. Foram revogados.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "19": "<p>Certo. Art. 57, § 2º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "20": "<p>Certo. Redação dada pela LC 227/2026.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "21": "<p>Errado. Art. 58, § 3º: podem manter sistemas próprios.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "22": "<p>Certo. Art. 60, caput.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "23": "<p>Errado. Art. 60, § 2º, II: obriga.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "24": "<p>Certo. Art. 60, § 4º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "25": "<p>Certo. Art. 60, § 7º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "26": "<p>Errado. O CNPJ cadastra as pessoas jurídicas; o CIB cadastra imóveis.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "27": "<p>Errado. Art. 61, caput: poderão instituir.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "28": "<p>Certo. Art. 62, § 1º, I.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "29": "<p>Errado. Art. 62, § 2º: até 31/12/2032.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "30": "<p>Certo. Art. 62, § 7º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "31": "<p>Certo. Art. 62, § 4º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>"};
